if value is None:
	# Priority: Comm Loss (Bad quality) wins over Fault/other Status enum
	# Bad quality means PLC bits cannot be trusted.
	tag_path = ''
	try:
		tag_path = self.view.params.tagPath or ''
	except:
		pass
	if str(tag_path).strip() == '':
		return ''
	q = ''
	try:
		q = str(self.custom.quality or '')
	except:
		pass
	if q.startswith('Bad'):
		return 'Comm Loss'
	return ''
try:
	v = int(value)
except:
	return ''
# Full-word status wall: Cooling/Idle/Defrost/Off/Fault/Comm Loss.
# Manual/Operator hidden. Defrost phase ints (6-9) collapse to Defrost.
codes = {0: 'Off', 1: 'Cooling', 2: 'Defrost', 3: 'Fault', 5: 'Idle', 6: 'Defrost', 7: 'Defrost', 8: 'Defrost', 9: 'Defrost'}
states = self.custom.states
if states:
	try:
		for s in states:
			sv = s['value'] if hasattr(s, '__getitem__') else getattr(s, 'value', None)
			sl = s['label'] if hasattr(s, '__getitem__') else getattr(s, 'label', None)
			if sv is not None and int(sv) == v and sl not in (None, ''):
				key = str(sl).strip().upper()
				alias = {
					'OFF': 'Off', 'STOP': 'Off', 'STOPPED': 'Off',
					'COOLING': 'Cooling', 'COOL': 'Cooling', 'CLG': 'Cooling',
					'DEFROST': 'Defrost', 'DEF': 'Defrost', 'DFT': 'Defrost',
					'1.PD': 'Defrost', '2.HG': 'Defrost', '3.BLD': 'Defrost', '3.FD': 'Defrost', '4.FD': 'Defrost',
					'PUMP DOWN': 'Defrost', 'HOT GAS': 'Defrost', 'BLEED': 'Defrost', 'FAN DELAY': 'Defrost',
					'FAULT': 'Fault', 'ALARM': 'Fault', 'FLT': 'Fault',
					'IDLE': 'Idle', 'STANDBY': 'Idle', 'IDL': 'Idle',
					'RUN': 'Cooling', 'RUNNING': 'Cooling', 'ON': 'Cooling',
					'COMM LOSS': 'Comm Loss', 'COMMLOSS': 'Comm Loss', 'COMM': 'Comm Loss'
				}
				# Manual/Operator -- do not surface as status code
				if key in ('MANUAL', 'MAN', 'OPERATOR') or v == 4:
					return ''
				# Cooling value always Cooling (never RUN)
				if v == 1:
					return 'Cooling'
				if v in (6, 7, 8, 9):
					return 'Defrost'
				return alias.get(key, codes.get(v, ''))
	except:
		pass
if v == 4:
	return ''
return codes.get(v, '')

